window.kbPageData["views/entry/k-8b07a2246ff7cebf"] = {"key":"entry/k-8b07a2246ff7cebf","state":{"route":"entry/k-8b07a2246ff7cebf"},"node":{"id":"k-8b07a2246ff7cebf","mode":"k","title":"宗教中国化","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"2.宗教中国化\n要总结运用历史经验，立足我国宗教工作实际，强化系统观念，加强体制规范建设，加\n强综合治理，加强基层基础工作，系统推进我国宗教中国化，积极引导宗教与社会主义社会\n相适应。\n我国是中国共产党领导的社会主义国家，积极引导宗教与社会主义社会相适应是必然要\n求。要坚持以社会主义核心价值观为引领…","sources":[{"id":"3e5eac35d5287c86","label":"宗教中国化","topic":"发展与治理","category":"非时政","text":"2.宗教中国化\n要总结运用历史经验，立足我国宗教工作实际，强化系统观念，加强体制规范建设，加\n强综合治理，加强基层基础工作，系统推进我国宗教中国化，积极引导宗教与社会主义社会\n相适应。\n我国是中国共产党领导的社会主义国家，积极引导宗教与社会主义社会相适应是必然要\n求。要坚持以社会主义核心价值观为引领，引导宗教界人士和信教群众牢固树立正确的国家\n观、历史观、民族观、文化观、宗教观，不断增进“五个认同”，自觉投身中国式现代化建\n设。\n——《习近平在中共中央政治局第二十二次集体学习时的讲话》","source":{"doc":"6cbfb01fe723bba64b75","first":53,"last":53,"page":53,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-8b07a2246ff7cebf":[]}};
